<?php require 'lib.php';head('ห้องว่าง');
$max=(float)($_GET['max']??0);$ty=$_GET['type']??'';
$sql="SELECT r.*,(SELECT file FROM room_images WHERE room_id=r.id ORDER BY id LIMIT 1) cover FROM rooms r WHERE status='vacant'";$a=[];if($max){$sql.=' AND rent<=?';$a[]=$max;}if($ty){$sql.=' AND type=?';$a[]=$ty;}
$rs=q($sql.' ORDER BY rent',$a)->fetchAll();$types=q('SELECT DISTINCT type FROM rooms WHERE type IS NOT NULL')->fetchAll(PDO::FETCH_COLUMN);?>
<div class="hero"><h1>ห้องพักว่าง พร้อมเข้าอยู่ ✨</h1><p>สะอาด ปลอดภัย ใช้งานระบบออนไลน์ได้ทุกขั้นตอน</p></div>
<?php $st=q("SELECT COUNT(*) t,SUM(type='แอร์') a,SUM(type='พัดลม') f,SUM(status='vacant') v,SUM(status='vacant' AND type='แอร์') va,SUM(status='vacant' AND type='พัดลม') vf FROM rooms")->fetch();?>
<div class="grid"><div class="card stat"><small>ห้องพักทั้งหมด</small><b><?=(int)$st['t']?> ห้อง</b>ห้องแอร์ <?=(int)$st['a']?> · ห้องพัดลม <?=(int)$st['f']?></div><div class="card stat"><small>ห้องว่างตอนนี้</small><b><?=(int)$st['v']?> ห้อง</b>ห้องแอร์ <?=(int)$st['va']?> · ห้องพัดลม <?=(int)$st['vf']?></div></div>
<form class="card row"><select name="type"><option value="">ทุกประเภท</option><?php foreach($types as $t)echo '<option '.($t==$ty?'selected':'').'>'.e($t).'</option>';?></select><input type="number" name="max" placeholder="ราคาไม่เกิน" value="<?=$max?:''?>"><button>ค้นหา</button></form>
<div class="grid"><?php foreach($rs as $r):?><div class="card room"><?=$r['cover']?'<img class="cv" src="uploads/'.e($r['cover']).'">':'<div class="cv ph">ยังไม่มีรูป</div>'?><h3>ห้อง <?=e($r['room_no'])?></h3><?=badge('vacant')?><p><?=e($r['type'])?><br><small><?=e($r['descr'])?></small></p><b style="color:var(--pd);font-size:1.3rem">฿<?=baht($r['rent'])?></b>/เดือน<br><br><a class="btn pk" href="book.php?room=<?=$r['id']?>">จองห้องนี้</a></div><?php endforeach;if(!$rs)echo '<p>ไม่พบห้องว่างตามเงื่อนไข</p>';?></div>
<?php $ex=q("SELECT r.room_no,r.type,r.rent,l.end_date FROM leases l JOIN rooms r ON r.id=l.room_id WHERE l.status='active' AND l.end_date>=CURDATE() AND l.end_date<=CURDATE()+INTERVAL 60 DAY ORDER BY l.end_date")->fetchAll();if($ex):?><h2 style="margin-top:28px">ห้องที่กำลังจะหมดสัญญาเช่า <small style="font-weight:400">(ภายใน 60 วัน · คาดว่าจะว่าง)</small></h2><div class="grid"><?php foreach($ex as $x):?><div class="card room"><h3>ห้อง <?=e($x['room_no'])?></h3><span class="b b-pending">ใกล้หมดสัญญา</span><p><?=e($x['type'])?><br>คาดว่าจะว่างหลังวันที่ <b><?=thdate($x['end_date'])?></b> (อีก <?=daysleft($x['end_date'])?> วัน)</p><b style="color:var(--pd);font-size:1.2rem">฿<?=baht($x['rent'])?></b>/เดือน<br><small>สนใจสอบถามเจ้าของหอพัก</small></div><?php endforeach;?></div><?php endif;?>
<?php foot();
